<span class="line"><span style="color:#61AFEF;">dotnet-dump</span><span style="color:#98C379;"> collect</span><span style="color:#D19A66;"> -p</span><span style="color:#ABB2BF;"> &lt;</span><span style="color:#98C379;">pi</span><span style="color:#ABB2BF;">d&gt;</span></span>
